samples.second_piece:
If we always start with the C and continue to read the rest of the letters in order clockwise, in how many different orders can the letters appear?

[asy]
draw(circle((0,0),1),dashed);
label("U",dir(90));
label("C",dir(90+360/5));
label("O",dir(90+2*360/5));
label("N",dir(90+3*360/5));
label("T",dir(90+4*360/5));
[/asy]

Given that $\overline{AC}$ is 3 units long, how many square units, expressed in simplest radical form, are in the area of the entire star? [asy]
import olympiad; import geometry; import graph; size(150); defaultpen(linewidth(0.8));
pair[] vertices;
for(int i = 0; i < 6; ++i){

vertices[i] = dir(30 + 60*i);
}
draw(vertices[0]--vertices[2]--vertices[4]--cycle);
draw(vertices[1]--vertices[3]--vertices[5]--cycle);
label("$D$",vertices[0],NE); label("$C$",vertices[1],N); label("$B$",vertices[2],NW); label("$A$",vertices[3],SW);
label("$F$",vertices[4],S); label("$E$",vertices[5],SE);
[/asy]

Express the area of the circle in terms of $\pi$. [asy]
size(200); import graph; import markers; defaultpen(linewidth(0.7));
xaxis("$x$",-5,11,Arrows);
yaxis("$y$",-7,7,Arrows);
draw(Circle((3,1),5));
dot(Label("$C(3,1)$",align=N),(3,1));
dot(Label("$(8,1)$",align=N),(8,1));
[/asy]

Use 3.14 as an approximation for $\pi$, and express your answer as a decimal to the nearest tenth.

[asy]import graph;
size(200);
picture p;
real h = .25,w = 1,textsize = 10pt,width = 1;
filldraw(Arc((8,0),8,0,180)--cycle,gray(.6),black+linewidth(width));
filldraw(Arc((6,0),6,0,180)--cycle,white,black+linewidth(width));
filldraw(Arc((4,0),4,0,180)--cycle,gray(.6),black+linewidth(width));
filldraw(Arc((2,0),2,0,180)--cycle,white,black+linewidth(width));
draw(p,(0,h)--(0,-h)^^(0,0)--(4,0)^^(4,h)--(4,-h),linewidth(width));
fill(p,(w,h)--(4-w,h)--(4-w,-h)--(w,-h)--cycle,white);
label(p,"4 cm",(2,0),fontsize(textsize));
add(shift(.5*down)*p);
add(shift(4*right)*shift(.5*down)*p);
add(shift(8*right)*shift(.5*down)*p);
add(shift(12*right)*shift(.5*down)*p);[/asy]

Give your answer as a mixed fraction.

[asy]
unitsize(0.6inch);
fill((0,0)--(1,0)..(rotate(60)*(1,0))..(rotate(120)*(1,0))--cycle,gray(0.6));
draw(Circle((0,0),1));
draw((1,0)--(0,0)--(rotate(120)*(1,0)));
label("$120^\circ$",(0,0),NE);
[/asy]

$EM$ is drawn from $E$ to $DF$ (a close-up is shown below), and if $x$ is the length of $EM,$ then what is $x^2?$

[asy]
draw((0,0)--(2.8284,-2.8284)--(5.6568,0)--cycle,black+linewidth(1));
draw((2.8284,0)--(2.8284,-2.8284),black+linewidth(1)+dashed);
draw((2.8284,0)--(3.0784,0)--(3.0784,-0.25)--(2.8284,-0.25)--cycle,black+linewidth(1));
label("$D$",(0,0),N);
label("$E$",(2.8284,-2.8284),S);
label("$F$",(5.6568,0),N);
label("$M$",(2.8284,0),N);
[/asy]

